INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l89','a slip of the tongue','',NULL,'/ə slɪp əv ðə tʌŋ/','A small slip of the tongue needn''t ruin the evening.','一个小口误不必毁掉整个晚上。','Calling her by the wrong name was just a slip of the tongue.','把她叫错名字只是个口误。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l89','be hard on','',NULL,'/bi hɑːrd ɑːn/','You mustn''t be so hard on yourself.','你别太苛责自己了。','Don''t be too hard on the new student.','别对新来的学生太严厉。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l89','mix up','',NULL,'/mɪks ʌp/','He must have mixed up the names.','他一定是把名字弄混了。','I always mix up those two words.','我总是把那两个词弄混。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l89','keep going','',NULL,'/kiːp ˈɡoʊɪŋ/','You should be proud — you kept going!','你该骄傲——你坚持下来了!','It was hard, but she kept going.','尽管很难,她还是坚持了下去。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp1','choice','{"stem":"\"''You ___ stay calm on stage,'' the teacher said.\"(主观上“必须、务必”)","options":["would","may","can","must"],"answer_index":3,"stem_cn":"“上台一定要沉住气,”老师说。","explanation_cn":"主观上“必须、务必”,用 must + 动词原形。✓ You must stay calm on stage. ✗ can:能够(表能力);✗ may:也许、可以(表许可/可能);✗ would:意愿/委婉,不表“必须”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp1','choice','{"stem":"\"He was so nervous that he ___ mixed up the names.\"(对过去的肯定推测:一定是)","options":["can have","should have","must have","must"],"answer_index":2,"stem_cn":"他太紧张了,一定是把名字说混了。","explanation_cn":"对过去的肯定推测“一定……过了”,用 must have + 过去分词。✓ He must have mixed up the names. ✗ must:只表现在“必须”,不表对过去的推测;✗ should have:是“本应做却没做”;✗ can have:不用于肯定推测。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp1','choice','{"stem":"\"''Next time, I ___ remember to breathe first,'' he laughed.\"(必须、一定要)","options":["must","would","might","could"],"answer_index":0,"stem_cn":"“下次我一定记得先深呼吸,”他笑道。","explanation_cn":"“一定要、必须”,用 must + 原形。✓ Next time, I must remember to breathe first. ✗ could:能够/也许;✗ might:也许;✗ would:意愿,不表“必须”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp2','choice','{"stem":"\"That evening, the host ___ introduce a famous writer.\"(过去客观上不得不)","options":["must","has to","would","had to"],"answer_index":3,"stem_cn":"那天晚上,主持人要介绍一位著名作家。","explanation_cn":"过去客观上“不得不”,用 had to + 原形。✓ The host had to introduce a famous writer. ✗ must:没有过去式,不表过去客观必须;✗ has to:一般现在;✗ would:不表“不得不”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp2','choice','{"stem":"\"Actors ___ practice a lot before a big show.\"(客观上必须)","options":["are to","must to","have to","has to"],"answer_index":2,"stem_cn":"演员在大型演出前必须多加排练。","explanation_cn":"客观上“必须”,用 have to + 原形。✓ Actors have to practice a lot. ✗ must to:must 后不加 to;✗ has to:主语是复数 actors,应用 have to;✗ are to:表“按安排要”,与“客观必须”不同。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp2','choice','{"stem":"\"Yesterday she ___ leave early to catch a train.\"(过去客观上不得不)","options":["will have to","must","has to","had to"],"answer_index":3,"stem_cn":"昨天她不得不早走去赶火车。","explanation_cn":"过去客观上“不得不”,用 had to。✓ Yesterday she had to leave early. ✗ must:不表过去;✗ has to:一般现在;✗ will have to:将来。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp3','choice','{"stem":"\"''You ___ be perfect,'' the teacher said.\"(不必、没必要)","options":["don''t have to","should","must not","have to"],"answer_index":0,"stem_cn":"“你不必做到完美,”老师说。","explanation_cn":"“不必、没必要”,用 don''t have to + 原形。✓ You don''t have to be perfect. ✗ must not:是“禁止、一定别”,意思相反;✗ have to:是“必须”;✗ should:是“应该”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp3','choice','{"stem":"\"''You ___ worry,'' the writer whispered.\"(不必、无需)","options":["must","needn''t","should","mustn''t"],"answer_index":1,"stem_cn":"“你不用担心,”作家轻声说。","explanation_cn":"“不必、无需”,用 needn''t + 原形。✓ You needn''t worry. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp3','choice','{"stem":"\"A small slip ___ ruin a good evening.\"(不必、无需)","options":["must","has to","mustn''t","needn''t"],"answer_index":3,"stem_cn":"一个小口误不必毁掉一个愉快的夜晚。","explanation_cn":"“不必、无需”,用 needn''t。✓ A small slip needn''t ruin a good evening. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ has to:是“必须”。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp4','choice','{"stem":"\"''You ___ speak clearly,'' the teacher said.\"(应该)","options":["should","would","must have","need"],"answer_index":0,"stem_cn":"“你应该吐字清楚,”老师说。","explanation_cn":"“应该”,用 should + 原形。✓ You should speak clearly. ✗ must have:对过去的推测;✗ need:此处不搭;✗ would:不表“应该”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp4','choice','{"stem":"\"''I ___ practiced more,'' the host said afterward.\"(过去本应做却没做)","options":["had to","should","must","should have"],"answer_index":3,"stem_cn":"“我当时真该多练练的,”主持人事后说。","explanation_cn":"“过去本应做而没做”,用 should have + 过去分词。✓ I should have practiced more. ✗ should:只表“应该”,不表“本应做却没做”;✗ must:必须;✗ had to:过去不得不(实际做了)。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp4','choice','{"stem":"\"''You ___ be proud — you kept going!'' she said.\"(应该)","options":["would have","must have","should","need"],"answer_index":2,"stem_cn":"“你该为自己骄傲——你坚持下来了!”她说。","explanation_cn":"“应该”,用 should。✓ You should be proud. ✗ must have:对过去的推测;✗ need:不搭;✗ would have:与过去相反的假设。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp5','choice','{"stem":"\"''You ___ be so hard on yourself,'' she replied.\"(表示“别、禁止这样”)","options":["mustn''t","have to","must","are to"],"answer_index":0,"stem_cn":"“别太苛责自己了,”她回答。","explanation_cn":"“禁止、一定别”,用 mustn''t + 原形。✓ You mustn''t be so hard on yourself. ✗ must:是“必须”,意思相反;✗ have to:是“必须”;✗ are to:表安排。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp5','choice','{"stem":"\"He didn''t prepare, so he ___ have mixed up the names.\"(对过去的肯定推测)","options":["would","must","need","should"],"answer_index":1,"stem_cn":"他没准备,所以一定是把名字说混了。","explanation_cn":"对过去的肯定推测,用 must have done(此处 must + have)。✓ He must have mixed up the names. ✗ need:不用于肯定推测;✗ should:表“本应”;✗ would:不表推测。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp5','choice','{"stem":"\"There''s no rule about it; you ___ come if you don''t want to.\"(主观上不必)","options":["mustn''t","must","don''t have to","have to"],"answer_index":2,"stem_cn":"这事没规定,你要是不想来就不必来。","explanation_cn":"主观上“不必”,用 don''t have to + 原形。✓ You don''t have to come if you don''t want to. ✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ have to:是“必须”。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp6','choice','{"stem":"\"The new ___ welcomed everyone to the show.\"(主持人用哪个词)","options":["driver","cook","farmer","host"],"answer_index":3,"stem_cn":"新主持人欢迎大家来看演出。","explanation_cn":"节目的“主持人”是 host。✓ The new host welcomed everyone. ✗ cook:厨师;✗ driver:司机;✗ farmer:农民。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp6','choice','{"stem":"\"He was very ___ before speaking to the crowd.\"(紧张的用哪个词)","options":["nervous","sleepy","hungry","angry"],"answer_index":0,"stem_cn":"在对众人讲话前,他非常紧张。","explanation_cn":"“紧张的”是 nervous。✓ He was very nervous. ✗ sleepy:困的;✗ hungry:饿的;✗ angry:生气的。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',5,'am2_l89_gp6','choice','{"stem":"\"''Try to stay ___,'' the teacher said.\"(镇静的、冷静的用哪个词)","options":["lost","calm","late","loud"],"answer_index":1,"stem_cn":"“尽量保持冷静,”老师说。","explanation_cn":"“镇静的、冷静的”是 calm。✓ Try to stay calm. ✗ loud:大声的;✗ late:迟的;✗ lost:迷路的。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"美语里\"剧院\"说:","options":["playhouse","showroom","theatre","theater"],"answer_index":3,"explanation_cn":"美语“剧院”说 theater;英式说 theatre。✓ The show was held at the theater. 演出在剧院举行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"美语里\"电梯\"说:","options":["elevator","riser","lift","mover"],"answer_index":0,"explanation_cn":"美语“电梯”说 elevator;英式说 lift。✓ Take the elevator to the top floor. 乘电梯到顶层。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"host 的意思是:","options":["观众","演员","主持人","作家"],"answer_index":2,"explanation_cn":"host = 主持人。✓ the new host 新主持人。\n顺带记:观众 = audience;演员 = actor;作家 = writer."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"nervous 的意思是:","options":["生气的","疲惫的","快乐的","紧张的"],"answer_index":3,"explanation_cn":"nervous = 紧张的。✓ He was so nervous 他非常紧张。\n顺带记:快乐的 = happy;疲惫的 = tired;生气的 = angry."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"introduce 的意思是:","options":["隐藏","介绍","责备","离开"],"answer_index":1,"explanation_cn":"introduce = 介绍。✓ introduce a famous writer 介绍一位著名作家。\n顺带记:责备 = blame;离开 = leave;隐藏 = hide."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',6,NULL,'choice','{"stem":"ruin 的意思是:","options":["建造","表扬","修理","毁掉,糟蹋"],"answer_index":3,"explanation_cn":"ruin = 毁掉、糟蹋。✓ needn''t ruin a good evening 不必毁掉一个愉快的夜晚。\n顺带记:建造 = build;修理 = repair;表扬 = praise."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',7,NULL,'cloze','{"stem":"第 1 空","context":"\"You ___1___ stay calm on stage,\" the teacher said. \"You ___2___ be perfect, but you should speak clearly.\" That evening, the host ___3___ introduce a famous writer. \"You ___4___ worry,\" the writer whispered.","blank_no":1,"options":["must","can","may","would"],"answer_index":0,"explanation_cn":"主观上“必须、务必”,用 must。✓ You must stay calm on stage.\n✗ can:能够;✗ may:也许/可以;✗ would:意愿。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',7,NULL,'cloze','{"stem":"第 2 空","context":"\"You ___1___ stay calm on stage,\" the teacher said. \"You ___2___ be perfect, but you should speak clearly.\" That evening, the host ___3___ introduce a famous writer. \"You ___4___ worry,\" the writer whispered.","blank_no":2,"options":["don''t have to","must not","have to","should"],"answer_index":0,"explanation_cn":"“不必、没必要”,用 don''t have to。✓ You don''t have to be perfect.\n✗ must not:是“禁止”;✗ have to:是“必须”;✗ should:是“应该”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',7,NULL,'cloze','{"stem":"第 3 空","context":"\"You ___1___ stay calm on stage,\" the teacher said. \"You ___2___ be perfect, but you should speak clearly.\" That evening, the host ___3___ introduce a famous writer. \"You ___4___ worry,\" the writer whispered.","blank_no":3,"options":["had to","must","has to","would"],"answer_index":0,"explanation_cn":"过去客观上“不得不”,用 had to。✓ The host had to introduce a famous writer.\n✗ must:不表过去;✗ has to:一般现在;✗ would:不表“不得不”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',7,NULL,'cloze','{"stem":"第 4 空","context":"\"You ___1___ stay calm on stage,\" the teacher said. \"You ___2___ be perfect, but you should speak clearly.\" That evening, the host ___3___ introduce a famous writer. \"You ___4___ worry,\" the writer whispered.","blank_no":4,"options":["needn''t","mustn''t","must","should"],"answer_index":0,"explanation_cn":"“不必、无需”,用 needn''t。✓ You needn''t worry.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',8,NULL,'choice','{"stem":"What did the teacher tell the new host to do?","options":["Leave early","Speak very fast","Stay calm on stage","Read a script"],"answer_index":2,"explanation_cn":"课文说 \"You must stay calm on stage,\" the teacher told the new host。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',8,NULL,'choice','{"stem":"What did the host have to do that evening?","options":["Introduce a famous writer","Clean the stage","Sing a song","Sell tickets"],"answer_index":0,"explanation_cn":"课文说 That evening, the host had to introduce a famous writer。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',8,NULL,'choice','{"stem":"What did the writer say about the slip?","options":["It was unforgivable","It ruined the evening","It never happens","It happens to everyone"],"answer_index":3,"explanation_cn":"课文说 \"You needn''t worry,\" the writer whispered kindly. \"It happens to everyone.\""}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',9,NULL,'choice','{"stem":"你想说\"那天晚上主持人得介绍一位著名作家\"(过去客观上必须,用 had to):","options":["That evening, the host had to introduce a famous writer.","That evening, the host had introduce a famous writer.","That evening, the host must introduce a famous writer.","That evening, the host has to introduce a famous writer."],"answer_index":0,"explanation_cn":"过去客观上“不得不”,用 had to + 原形。✓ That evening, the host had to introduce a famous writer. 场合:说过去因客观原因必须做某事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',9,NULL,'choice','{"stem":"你想说\"你不必做到完美\"(不必,用 don''t have to):","options":["You haven''t to be perfect.","You don''t have to be perfect.","You don''t must be perfect.","You mustn''t be perfect."],"answer_index":1,"explanation_cn":"“不必、没必要”,用 don''t have to + 原形。✓ You don''t have to be perfect. 场合:告诉别人某事没必要做。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',9,NULL,'choice','{"stem":"你想说\"我当时应该多练练的\"(过去本应做却没做,用 should have done):","options":["I must have practiced more.","I had to practice more.","I should have practiced more.","I should practice more."],"answer_index":2,"explanation_cn":"“过去本应做却没做”,用 should have + 过去分词。✓ I should have practiced more. 场合:事后为没做某事而后悔。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"host 的意思是:","options":["演员","观众","作家","主持人"],"answer_index":3,"explanation_cn":"host = 主持人。✓ the new host 新主持人。\n顺带记:观众 = audience;演员 = actor;作家 = writer."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"nervous 的意思是:","options":["快乐的","紧张的","疲惫的","生气的"],"answer_index":1,"explanation_cn":"nervous = 紧张的。✓ He was so nervous 他非常紧张。\n顺带记:快乐的 = happy;疲惫的 = tired;生气的 = angry."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"\"That evening, the host ___ introduce a famous writer.\"(过去客观上必须)","options":["had to","has to","must","would"],"answer_index":0,"stem_cn":"那天晚上,主持人要介绍一位著名作家。","explanation_cn":"过去客观上“不得不”,用 had to。✓ The host had to introduce a famous writer.\n✗ must:不表过去;✗ has to:一般现在;✗ would:不表“不得不”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"\"''You ___ worry,'' the writer whispered.\"(不必、无需)","options":["should","must","mustn''t","needn''t"],"answer_index":3,"stem_cn":"“你不用担心,”作家轻声说。","explanation_cn":"“不必、无需”,用 needn''t。✓ You needn''t worry.\n✗ mustn''t:是“禁止”;✗ must:是“必须”;✗ should:是“应该”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"\"a slip of the tongue\" 的意思是:","options":["滑了一跤","口误,说错话","舌头受伤","尝一口"],"answer_index":1,"explanation_cn":"a slip of the tongue = 口误、说错话(一时说漏嘴)。✓ a small slip needn''t ruin the evening。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"\"keep going\" 的意思是:","options":["坚持下去,继续","保持不动","一直走开","反复出发"],"answer_index":0,"explanation_cn":"keep going = 坚持下去、继续。✓ You should be proud — you kept going!"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"What did the teacher tell the host to do on stage?","options":["Read fast","Sit down","Stay calm","Sing loudly"],"answer_index":2,"passage":"\"You must stay calm on stage,\" the teacher told the new host. \"You don''t have to be perfect, but you should speak clearly.\" That evening, the host had to introduce a famous writer. He was so nervous that he must have mixed up the names. \"You needn''t worry,\" the writer whispered kindly. \"It happens to everyone.\" \"I should have practiced more,\" the host said afterward. \"You mustn''t be so hard on yourself,\" she replied with a smile. \"Next time, I must remember to breathe first,\" he laughed. \"You should be proud — you kept going!\" she said. Everyone agreed: a small slip needn''t ruin a good evening.","explanation_cn":"课文说 \"You must stay calm on stage,\" the teacher said——叫他保持冷静。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"What did the host say he should have done?","options":["Practiced more","Left earlier","Stayed home","Written a book"],"answer_index":0,"passage":"\"You must stay calm on stage,\" the teacher told the new host. \"You don''t have to be perfect, but you should speak clearly.\" That evening, the host had to introduce a famous writer. He was so nervous that he must have mixed up the names. \"You needn''t worry,\" the writer whispered kindly. \"It happens to everyone.\" \"I should have practiced more,\" the host said afterward. \"You mustn''t be so hard on yourself,\" she replied with a smile. \"Next time, I must remember to breathe first,\" he laughed. \"You should be proud — you kept going!\" she said. Everyone agreed: a small slip needn''t ruin a good evening.","explanation_cn":"课文说 \"I should have practiced more,\" the host said afterward。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"What did the writer say about small slips?","options":["They ruin everything","They happen to everyone","They are unforgivable","They never happen"],"answer_index":1,"audio":"\"You must stay calm on stage,\" the teacher told the new host. \"You don''t have to be perfect, but you should speak clearly.\" That evening, the host had to introduce a famous writer. He was so nervous that he must have mixed up the names. \"You needn''t worry,\" the writer whispered kindly. \"It happens to everyone.\" \"I should have practiced more,\" the host said afterward. \"You mustn''t be so hard on yourself,\" she replied with a smile. \"Next time, I must remember to breathe first,\" he laughed. \"You should be proud — you kept going!\" she said. Everyone agreed: a small slip needn''t ruin a good evening.","explanation_cn":"课文说 \"It happens to everyone,\" the writer said——小口误人人都会有。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l89',10,NULL,'choice','{"stem":"What did the teacher tell the host at the start?","options":["Stay calm on stage","Speak very fast","Read a script","Skip the show"],"answer_index":0,"audio":"\"You must stay calm on stage,\" the teacher told the new host. \"You don''t have to be perfect, but you should speak clearly.\" That evening, the host had to introduce a famous writer. He was so nervous that he must have mixed up the names. \"You needn''t worry,\" the writer whispered kindly. \"It happens to everyone.\" \"I should have practiced more,\" the host said afterward. \"You mustn''t be so hard on yourself,\" she replied with a smile. \"Next time, I must remember to breathe first,\" he laughed. \"You should be proud — you kept going!\" she said. Everyone agreed: a small slip needn''t ruin a good evening.","explanation_cn":"课文说 \"You must stay calm on stage,\" the teacher told the new host。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l90',2,12,90,'What''s for Dinner?','晚饭吃什么?','复习 KS17/41/65 情态表达(方案B换情节包):must(必须;对现在的肯定推测)、have to / had to(客观上必须)、needn''t 与 don''t have to(不必)、should(应该、建议)的用法,以及 must 与 have to 的区别','“我们该动手做饭了,”妈妈说,“爸爸六点到家。”“我们得先去买东西吗?”我问。“不用,该有的都有了。”“帮忙前你必须先洗手,”妈妈提醒我。“我来切菜吗?”我问。“好,不过用刀要小心。”“我们不用赶——晚饭六点半好就行。”“这汤闻着真香,一定特别好喝,”弟弟说。“做好了你尝尝,”妈妈笑道。“我们真该多一起做饭——太有意思了!”','{"q":"Listen and answer — When will Dad be home for dinner?","options":["At six","At five","At seven","At eight"],"answer_index":0}'::jsonb,'{"title":"复习 KS17/41/65 情态表达","intro":"本课在做晚饭的场景里复习几个常用的情态说法:①must——“必须、务必”(You must wash your hands),也可表对现在的肯定推测“一定”(This soup must taste amazing);②have to / had to——客观上“不得不、必须”(Do we have to go shopping?);③needn''t 和 don''t have to——“不必、无需”(We needn''t / We don''t have to hurry);④should——“应该、建议”(We should start cooking soon);⑤must 与 have to 的区别:must 常表说话人主观的看法或强烈建议,have to 常表外在的客观要求。","table":{"headers":["表达","例子"],"rows":[["must / 推测","You must wash your hands. / This soup must taste amazing."],["have to / had to","Do we have to go shopping first?"],["needn''t / don''t have to","We needn''t hurry. / We don''t have to hurry."],["should","We should start cooking soon."],["must vs have to","must = 主观看法/建议;have to = 客观要求。"]]},"specialRules":[{"rule":"美语“炉灶”说 stove(英式 cooker);“水龙头”说 faucet(英式 tap)。本课已按美语写。","mark":"stove / faucet"},{"rule":"needn''t / don''t have to = 不必;must 也可表“一定(推测)”;must 多表说话人主观强烈的看法或建议,have to 多表外在客观的要求。","mark":"情态辨析"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l90',1,NULL,'"We should start cooking soon," Mom said. "Dad will be home at six." "Do we have to go shopping first?" I asked.','“我们该动手做饭了,”妈妈说,“爸爸六点到家。”“我们得先去买东西吗?”我问。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l90',2,NULL,'"No, we needn''t. We have everything we need." "You must wash your hands before you help," Mom reminded me.','“不用,该有的都有了。”“帮忙前你必须先洗手,”妈妈提醒我。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l90',3,NULL,'"Should I chop the vegetables?" I asked. "Yes, but you must be careful with the knife."','“我来切菜吗?”我问。“好,不过用刀要小心。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l90',4,NULL,'"We don''t have to hurry — dinner needn''t be ready until six-thirty." "This soup must taste amazing," said my brother. "It smells great!"','“我们不用赶——晚饭六点半好就行。”“这汤闻着真香,一定特别好喝,”弟弟说。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l90',5,NULL,'"You should try it when it''s done," Mom laughed. "We must cook together more often — it''s fun!"','“做好了你尝尝,”妈妈笑道。“我们真该多一起做饭——太有意思了!”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
